   private String name;
   private ResourceLocation texture;
   private ResourceLocation pedestalTexture;

   private EnumMemorials(String name, ResourceLocation texture, ResourceLocation pedestalTexture) {
      this.name = name;
      this.texture = texture;
      this.pedestalTexture = pedestalTexture;
   }

   public String getName() {
      return ModGraveStone.proxy.getLocalizedString(this.name);
   }

   public ResourceLocation getTexture() {
      return this.texture;
   }

   public ResourceLocation getPedestalTexture() {
      return this.pedestalTexture;
   }

   public static EnumMemorials getByID(int id) {
      return id < values().length ? values()[id] : STONE_CROSS;
   }
